"""Learning content — Mine to Port catalog, Area A01 Mine (generic 2 Mt/yr low-temperature Bayer reference plant).
Numbers are typical published envelopes for each equipment class and engineering estimates from the reference-plant
design basis (m2p/basis). They are knowledge-based and must be verified against the selected OEM data."""
from pumpforge.learning import mod, step, P, F, Q, M

MODULES = {}

BASIS = ('Reference-plant values: typical published envelope for this equipment class plus engineering estimates from the '
         'Mine-to-Port design basis (generic 2 Mt/yr low-temperature Bayer refinery). Knowledge-based — not verified against a live '
         'source; confirm with the selected OEM specification and your site data before use.')
SOURCES = ['PumpForge Mine-to-Port reference-plant design basis (m2p/basis), multi-agent SME reviewed',
           'SME Mining Engineering Handbook, 3rd ed. (2011)', 'OEM performance handbooks for the equipment class (generic envelope)']


def _ref(**rated):
    return {'manufacturer': None, 'model': None, 'datasheet': None, 'rated_point': rated or {'capacity': None, 'power_kW': None},
            'status': 'empty — fill from the selected OEM specification sheet'}


